      _Unit('T2 • Série F4 • Topographie et implantation','Topographie et implantation','La topographie mesure distances, angles et dénivelés. L’implantation reporte sur le terrain les axes et points définis sur les plans.','Un nivellement détermine les différences d’altitude.','Quel est l’objectif du nivellement ?',["Déterminer les altitudes relatives","Mesurer la résistance électrique","Calculer la masse volumique"],0,'Le nivellement établit les différences de hauteur.'),
      _Unit('T3 • Série F4 • Conduite et réception de chantier','Conduite et réception de chantier','La conduite de chantier organise équipes, approvisionnements, sécurité, qualité et délais. La réception vérifie les ouvrages, réserve les défauts et organise leur levée.','Un procès-verbal de réception formalise les observations et réserves.','Que consigne une réception de travaux ?',["Conformités et réserves","Uniquement les salaires","Les notes des élèves"],0,'La réception constate l’état des travaux et les éventuelles réserves.'),
    ],
    'Ti/1' => [
      _Unit('T1 • Série Ti/1 • Automatisation industrielle','Automatisation industrielle','Un automatisme combine capteurs, préactionneurs, actionneurs et unité de traitement. Le grafcet décrit les étapes et transitions d’un cycle séquentiel.','Une transition devient franchissable lorsque sa réceptivité est vraie.','Que décrit un grafcet ?',["Le fonctionnement séquentiel d’un système","La comptabilité d’une entreprise","Un plan cadastral"],0,'Le grafcet formalise les étapes et transitions d’un automatisme.'),
      _Unit('T2 • Série Ti/1 • Maintenance prédictive','Maintenance prédictive','La maintenance prédictive exploite mesures et tendances pour anticiper une défaillance. Vibrations, température et intensité peuvent révéler une dérive.','Comparer une mesure à une tendance historique améliore le diagnostic.','Quel est l’objectif de la maintenance prédictive ?',["Anticiper les pannes","Attendre systématiquement la casse","Supprimer les mesures"],0,'Elle vise à intervenir avant la panne à partir d’indicateurs.'),
      _Unit('T3 • Série Ti/1 • Qualité et amélioration continue','Qualité et amélioration continue','L’amélioration continue analyse les causes racines, teste des actions et mesure les résultats. La traçabilité permet de capitaliser les corrections.','Une action corrective doit être vérifiée après mise en œuvre.','Pourquoi vérifier une action corrective ?',["Confirmer qu’elle élimine la cause","Ajouter des formulaires sans but","Cacher le défaut"],0,'La vérification confirme l’efficacité réelle de la correction.'),
    ],
    _ => const <_Unit>[],
  };
  static List<Exercise> assessmentExercisesForTerm(int term, {String? subjectName, SchoolTrack? track, String? series}) {
    final result = <Exercise>[];
    for (var i = 0; i < _units.length; i++) {
      final unit = _units[i];
      if (!unit.title.startsWith('T$term •')) continue;
      if (subjectName != null && !_matches(unit.title, subjectName)) continue;
      result.add(Exercise(id: 'term_t${term}_u${i}', lessonId: 'term_t${term}_u${i}', question: unit.question, options: unit.options, correctIndex: unit.answer, explanation: unit.explanation));
    }
    if (track != null && series != null) {
      final extra = seriesUnitsFor(series);
      for (var i = 0; i < extra.length; i++) {
        final unit = extra[i];
        if (!unit.title.startsWith('T$term •')) continue;
        if (subjectName != null && !_matches(unit.title, subjectName)) continue;
        final safeSeries = series.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'), '_');
        result.add(Exercise(id: 'term_${safeSeries}_t${term}_u${i}', lessonId: 'term_${safeSeries}_t${term}_u${i}', question: unit.question, options: unit.options, correctIndex: unit.answer, explanation: unit.explanation));
      }
    }
    return result;
  }
  static bool _matches(String title, String subject) {
    final t = title.toLowerCase(), s = subject.toLowerCase();
    if (s.contains('français') || s.contains('francais') || s.contains('littérature')) return t.contains('français');
    if (s.contains('math')) return t.contains('mathématiques');
    if (s.contains('anglais') || s.contains('english')) return t.contains('anglais');
    if (s.contains('svt') || s.contains('science') || s.contains('biologie')) return t.contains('svt');
    if (s.contains('physique') || s.contains('chimie')) return t.contains('physique-chimie');
    if (s.contains('histoire') || s.contains('géographie') || s.contains('education') || s.contains('éducation') || s.contains('emc')) return t.contains('histoire-géographie');
    return false;
  }
  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: Text('Complément Terminale • Série $series • BAC II')),
    body: ListView(padding: const EdgeInsets.all(16), children: [
      Card(child: Padding(padding: const EdgeInsets.all(16), child: Text('Parcours : ${track.label} • Série $series\n${unitCount} unités de consolidation • ${lessonCount} leçons • 3 trimestres\nÀ compléter par les matières et épreuves spécifiques de la série.', style: const TextStyle(fontWeight: FontWeight.w600)))),
      for (final unit in _units) _UnitTile(unit: unit),
      if (seriesUnitsFor(series).isNotEmpty) const Padding(padding: EdgeInsets.symmetric(vertical: 12), child: Text('ENSEIGNEMENTS SPÉCIFIQUES DE LA SÉRIE', style: TextStyle(fontWeight: FontWeight.bold, letterSpacing: 0.5))),
      for (final unit in seriesUnitsFor(series)) _UnitTile(unit: unit),
    ]),
  );
}
class _Unit {
  final String title, objective, content, example, question;
  final List<String> options;
  final int answer;
  final String explanation;
  const _Unit(this.title, this.objective, this.content, this.example, this.question, this.options, this.answer, this.explanation);
}
class _UnitTile extends StatefulWidget {
  final _Unit unit;
  const _UnitTile({required this.unit});
  @override State<_UnitTile> createState() => _UnitTileState();
}
class _UnitTileState extends State<_UnitTile> {
  int? choice;
  bool checked = false;
  @override Widget build(BuildContext context) {
    final unit = widget.unit;
    return Card(margin: const EdgeInsets.only(bottom: 10), child: ExpansionTile(
      title: Text(unit.title, style: const TextStyle(fontWeight: FontWeight.bold)),
      subtitle: Text(unit.objective),
      children: [Padding(padding: const EdgeInsets.fromLTRB(16, 0, 16, 16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(unit.content), const SizedBox(height: 8),
        Text('Exemple : ${unit.example}', style: const TextStyle(fontStyle: FontStyle.italic)),
        const SizedBox(height: 12), Text(unit.question, style: const TextStyle(fontWeight: FontWeight.bold)),
        for (var i = 0; i < unit.options.length; i++) RadioListTile<int>(dense: true, contentPadding: EdgeInsets.zero, value: i, groupValue: choice, title: Text(unit.options[i]), onChanged: checked ? null : (value) => setState(() => choice = value)),
        FilledButton.tonal(onPressed: choice == null ? null : () => setState(() => checked = true), child: const Text('Vérifier ma réponse')),
        if (checked) Text('${choice == unit.answer ? 'Bonne réponse ! ' : 'À revoir. Bonne réponse : ${unit.options[unit.answer]}. '}${unit.explanation}', style: TextStyle(fontWeight: FontWeight.w600, color: choice == unit.answer ? Colors.green.shade800 : Theme.of(context).colorScheme.error)),
        if (checked) TextButton(onPressed: () => setState(() { choice = null; checked = false; }), child: const Text('Recommencer')),
      ]))],
    ));
  }
}
